/* @autogenerated */
package net.civeira.phylax.feature.observe.viewer;

import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.issue.IssueAggregator;
import net.civeira.phylax.feature.observe.issue.IssueFingerprint;
import net.civeira.phylax.feature.observe.store.ObsLog;

class ObserveIssuesDetailUnitTest {

  private static final String STACK = "java.lang.IllegalStateException: boom\n"
      + "\tat com.acme.orders.OrderService.find(OrderService.java:10)\n"
      + "\tat io.vertx.core.impl.ContextImpl.run(ContextImpl.java:12)\n"
      + "\tat io.vertx.core.impl.Worker.run(Worker.java:3)";

  private static ObsLog event(final long ts, final String release, final String ua,
      final String tenant) {
    return new ObsLog(ts, "api", "ERROR", "com.acme.Svc", "boom", null, null, STACK,
        Map.of("user_agent.original", ua, "app.tenant", tenant), release, "prod");
  }

  @Test
  @DisplayName("Error logs are tagged with the fingerprint of their issue before storing them")
  void tag() {
    IssueAggregator aggregator = new IssueAggregator(null, null, true, "com.acme.", true, "salt");
    ObsLog info = new ObsLog(1, "api", "INFO", "x", "ok", null, null, null, Map.of(), null, null);
    List<ObsLog> tagged = aggregator.tag(List.of(event(1, "1.0", "curl/8", "acme"), info));
    Assertions.assertNotNull(tagged.get(0).attrs().get(IssueAggregator.FINGERPRINT_ATTR));
    Assertions.assertSame(info, tagged.get(1));
  }

  @Test
  @DisplayName("The stack marks the own frames; the library ones are frames but not own")
  void stack() {
    List<IssueFingerprint.Line> lines = IssueFingerprint.lines(STACK, List.of("com.acme."));
    Assertions.assertEquals(4, lines.size());
    Assertions.assertFalse(lines.get(0).frame());
    Assertions.assertTrue(lines.get(1).inApp());
    Assertions.assertTrue(lines.get(2).frame());
    Assertions.assertFalse(lines.get(2).inApp());
  }

  @Test
  @DisplayName("Histogram per hour of the last days and top values of the distribution")
  void histogramAndDistribution() {
    long now = 1_000 * 3_600_000L;
    List<ObsLog> events =
        List.of(event(now - 10, "1.1", "Mozilla/5.0 Chrome/120 Safari/537", "acme"),
            event(now - 20, "1.1", "Mozilla/5.0 Firefox/120", "acme"),
            event(now - 2 * 3_600_000L, "1.0", "curl/8.0", "globex"));
    Map<String, Object> histogram = ObserveIssues.histogram(events, now);
    long[] counts = (long[]) histogram.get("counts");
    Assertions.assertEquals(7 * 24, counts.length);
    Assertions.assertEquals(2, counts[counts.length - 2]);
    Assertions.assertEquals(1, counts[counts.length - 3]);
    Map<String, List<Map<String, Object>>> distribution = ObserveIssues.distribution(events);
    Assertions.assertEquals("1.1", distribution.get("release").get(0).get("value"));
    Assertions.assertEquals(2L, distribution.get("tenant").get(0).get("count"));
    Assertions.assertEquals("Chrome", ObserveIssues.browser("Mozilla/5.0 Chrome/120 Safari/537"));
    Assertions.assertEquals("Edge", ObserveIssues.browser("Mozilla/5.0 Chrome/120 Edg/120"));
    Assertions.assertEquals("unknown", ObserveIssues.browser(null));
  }
}
